dockerfile:
ARG BASE=debian:bookworm-slim
FROM ${BASE}

# Self-contained Deno runtime for the Gambit CLI (the harness is a Deno program).
ARG DENO_VERSION=2.9.7
ENV DENO_DIR=/opt/harness/deno-cache \
    DENO_NO_UPDATE_CHECK=1 \
    DENO_NO_PROMPT=1 \
    PATH=/opt/harness/bin:/opt/harness/deno/bin:$PATH

RUN apt-get update \
    && apt-get install -y --no-install-recommends ca-certificates curl unzip git bash \
    && rm -rf /var/lib/apt/lists/*

RUN set -eux; \
    arch="$(dpkg --print-architecture)"; \
    case "$arch" in \
      amd64) target=x86_64-unknown-linux-gnu ;; \
      arm64) target=aarch64-unknown-linux-gnu ;; \
      *) echo "unsupported arch: $arch" >&2; exit 1 ;; \
    esac; \
    mkdir -p /opt/harness/deno/bin; \
    curl -fsSL -o /tmp/deno.zip "https://github.com/denoland/deno/releases/download/v${DENO_VERSION}/deno-${target}.zip"; \
    unzip -q /tmp/deno.zip -d /opt/harness/deno/bin; \
    rm -f /tmp/deno.zip; \
    chmod +x /opt/harness/deno/bin/deno; \
    deno --version

# Harness source (unmodified) lives under /opt/harness/src.
COPY . /opt/harness/src

# Coding-agent deck: the "program" Gambit runs for a task. Gambit's runtime
# already exposes built-in read_file/list_dir/grep_files/apply_patch/exec tools,
# but they resolve relative paths against the deck directory and exec has a
# 30s cap, so the deck adds three compute actions that work in the task cwd.
RUN mkdir -p /opt/harness/decks/actions /opt/harness/bin

RUN cat > /opt/harness/decks/coding_agent.deck.md <<'EOF'
+++
label = "coding_agent"
description = "Autonomous coding agent that completes one task in the current working directory."

[modelParams]
model = "google/gemini-2.5-pro"
temperature = 0

[guardrails]
maxDepth = 3
maxPasses = 400
timeoutMs = 0

[[actions]]
name = "run_shell"
description = "Run a bash command line in the repository working directory (cwd) and return its exit code, stdout and stderr. Use it to list and search files, build, and run tests. Default timeout 600 seconds."
path = "./actions/run_shell.deck.ts"

[[actions]]
name = "write_file"
description = "Create or overwrite a file with the given full contents, creating parent directories as needed. Relative paths resolve against the repository working directory."
path = "./actions/write_file.deck.ts"

[[actions]]
name = "replace_in_file"
description = "Replace an exact substring of a file with new text. old_string must occur exactly once unless replace_all is true. Relative paths resolve against the repository working directory."
path = "./actions/replace_in_file.deck.ts"
+++

You are an autonomous software engineering agent working inside a repository.
The first user message states the absolute path of the repository working
directory and then the task.

Rules:

- Work non-interactively: nobody can answer questions, so make reasonable
  assumptions and proceed.
- Explore before changing: use `run_shell` (for example `ls`, `grep -rn`,
  `cat -n`, `sed -n`) to inspect files, then `replace_in_file` for targeted
  edits and `write_file` for new files or full rewrites. These three tools
  resolve relative paths against the repository working directory.
- The built-in tools `read_file`, `list_dir`, `grep_files`, `apply_patch` and
  `exec` resolve relative paths against a different directory, so if you use
  them, always pass absolute paths. Prefer `run_shell` over `exec`, which has
  no shell and a 30 second limit.
- Never modify files outside the repository working directory.
- Verify your work (run the tests or the program) before finishing when
  possible.
- Keep going until the task is complete. When it is complete, reply with a
  short plain-text summary of what you changed and how you verified it, and do
  not call any more tools.
EOF

RUN cat > /opt/harness/decks/actions/run_shell.deck.ts <<'EOF'
import { defineDeck } from "../../src/packages/gambit-core/mod.ts";
import { z } from "zod";

const LIMIT = 40_000;
const clip = (text: string) =>
  text.length > LIMIT
    ? { text: text.slice(0, LIMIT) + "\n...[truncated]", truncated: true }
    : { text, truncated: false };

export default defineDeck({
  label: "run_shell",
  contextSchema: z.object({
    command: z.string().describe("Bash command line to execute"),
    timeout_seconds: z.number().int().positive().max(3600).optional()
      .describe("Kill the command after this many seconds (default 600)"),
  }),
  responseSchema: z.object({
    exit_code: z.number(),
    stdout: z.string(),
    stderr: z.string(),
    truncated: z.boolean(),
    timed_out: z.boolean(),
  }),
  async run(ctx) {
    const timeoutMs = (ctx.input.timeout_seconds ?? 600) * 1000;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const out = await new Deno.Command("bash", {
        args: ["-lc", ctx.input.command],
        cwd: Deno.cwd(),
        stdin: "null",
        stdout: "piped",
        stderr: "piped",
        signal: controller.signal,
      }).output();
      const stdout = clip(new TextDecoder().decode(out.stdout));
      const stderr = clip(new TextDecoder().decode(out.stderr));
      return {
        exit_code: out.code,
        stdout: stdout.text,
        stderr: stderr.text,
        truncated: stdout.truncated || stderr.truncated,
        timed_out: controller.signal.aborted,
      };
    } catch (err) {
      return {
        exit_code: -1,
        stdout: "",
        stderr: err instanceof Error ? err.message : String(err),
        truncated: false,
        timed_out: controller.signal.aborted,
      };
    } finally {
      clearTimeout(timer);
    }
  },
});
EOF

RUN cat > /opt/harness/decks/actions/write_file.deck.ts <<'EOF'
import { defineDeck } from "../../src/packages/gambit-core/mod.ts";
import { z } from "zod";
import * as path from "@std/path";

export default defineDeck({
  label: "write_file",
  contextSchema: z.object({
    path: z.string().describe(
      "File path (relative to the working directory, or absolute)",
    ),
    content: z.string().describe("Full new contents of the file"),
  }),
  responseSchema: z.object({
    ok: z.boolean(),
    path: z.string(),
    bytes: z.number(),
    error: z.string().optional(),
  }),
  async run(ctx) {
    const target = path.resolve(Deno.cwd(), ctx.input.path);
    try {
      await Deno.mkdir(path.dirname(target), { recursive: true });
      await Deno.writeTextFile(target, ctx.input.content);
      return {
        ok: true,
        path: target,
        bytes: new TextEncoder().encode(ctx.input.content).length,
      };
    } catch (err) {
      return {
        ok: false,
        path: target,
        bytes: 0,
        error: err instanceof Error ? err.message : String(err),
      };
    }
  },
});
EOF

RUN cat > /opt/harness/decks/actions/replace_in_file.deck.ts <<'EOF'
import { defineDeck } from "../../src/packages/gambit-core/mod.ts";
import { z } from "zod";
import * as path from "@std/path";

export default defineDeck({
  label: "replace_in_file",
  contextSchema: z.object({
    path: z.string().describe(
      "File path (relative to the working directory, or absolute)",
    ),
    old_string: z.string().describe("Exact text to replace"),
    new_string: z.string().describe("Replacement text"),
    replace_all: z.boolean().optional()
      .describe("Replace every occurrence instead of requiring exactly one"),
  }),
  responseSchema: z.object({
    ok: z.boolean(),
    path: z.string(),
    replacements: z.number(),
    error: z.string().optional(),
  }),
  async run(ctx) {
    const target = path.resolve(Deno.cwd(), ctx.input.path);
    try {
      const text = await Deno.readTextFile(target);
      const count = text.split(ctx.input.old_string).length - 1;
      if (count === 0) {
        return {
          ok: false,
          path: target,
          replacements: 0,
          error: "old_string not found",
        };
      }
      if (count > 1 && !ctx.input.replace_all) {
        return {
          ok: false,
          path: target,
          replacements: 0,
          error:
            `old_string occurs ${count} times; add more context or set replace_all`,
        };
      }
      const updated = ctx.input.replace_all
        ? text.split(ctx.input.old_string).join(ctx.input.new_string)
        : text.replace(ctx.input.old_string, () => ctx.input.new_string);
      await Deno.writeTextFile(target, updated);
      return {
        ok: true,
        path: target,
        replacements: ctx.input.replace_all ? count : 1,
      };
    } catch (err) {
      return {
        ok: false,
        path: target,
        replacements: 0,
        error: err instanceof Error ? err.message : String(err),
      };
    }
  },
});
EOF

# Thin launcher for the Gambit CLI entrypoint (src/cli.ts). Same as the repo's
# bin/gambit, plus an explicit config, the offline module cache, and the
# unstable worker-options flag the worker sandbox needs (CI enables it too).
RUN cat > /opt/harness/bin/gambit <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
exec /opt/harness/deno/bin/deno run -A --unstable-worker-options --cached-only \
  --config /opt/harness/src/deno.jsonc --lock /opt/harness/deno.lock --frozen \
  /opt/harness/src/src/cli.ts "$@"
EOF
RUN chmod +x /opt/harness/bin/gambit \
    && printf 'export PATH=/opt/harness/bin:/opt/harness/deno/bin:$PATH\nexport DENO_DIR=/opt/harness/deno-cache DENO_NO_UPDATE_CHECK=1 DENO_NO_PROMPT=1\n' \
       > /etc/profile.d/harness.sh

# Pre-populate the Deno module cache (CLI graph, sandbox worker entrypoints and
# the deck actions) so no network is needed at run time. Resolution is pinned by
# a copy of the repo's deno.lock so the harness's own lockfile is never rewritten.
RUN cd /opt/harness/src && cp deno.lock /opt/harness/deno.lock \
    && deno install --entrypoint --config deno.jsonc --lock /opt/harness/deno.lock \
      src/cli.ts \
      packages/gambit-core/src/runtime_worker.ts \
      packages/gambit-core/src/runtime_orchestration_worker.ts \
      /opt/harness/decks/actions/run_shell.deck.ts \
      /opt/harness/decks/actions/write_file.deck.ts \
      /opt/harness/decks/actions/replace_in_file.deck.ts \
    && chmod -R a+rwX /opt/harness/deno-cache \
    && mkdir -p /out && chmod 777 /out
